class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        def count_up_to(digits: list, target_sum: int, dp_func) -> int:
            if not digits:
                return 0
            ans = 0

            # Count numbers with fewer digits than `digits` (avoids leading zero logic)
            for length in range(1, len(digits)):
                for first_digit in range(1, 10):
                    if first_digit <= target_sum:
                        ans += dp_func(length - 1, target_sum - first_digit, first_digit % target_sum)

            # Count numbers with exactly the same number of digits as `digits`
            cur_sum = 0
            prod_mod = 1 % target_sum

            for i, d in enumerate(digits):
                rem = len(digits) - 1 - i
                start_d = 1 if i == 0 else 0
                for x in range(start_d, d):
                    if cur_sum + x <= target_sum:
                        n_prod = (prod_mod * x) % target_sum
                        ans += dp_func(rem, target_sum - (cur_sum + x), n_prod)

                cur_sum += d
                prod_mod = (prod_mod * d) % target_sum
                if cur_sum > target_sum:
                    break
            else:
                # If we exactly match the boundary itself
                if cur_sum == target_sum and prod_mod == 0:
                    ans += 1

            return ans

        ans = 0
        R_digits = list(map(int, str(r)))
        L_digits = list(map(int, str(l - 1))) if l > 1 else []
        max_sum = 9 * len(R_digits)

        for target_sum in range(1, max_sum + 1):
            # Define DP inside to auto-clear the cache after each target_sum preventing Memory Limit Exceeded.
            # State only relies on length, sum, and product, vastly reducing caching overhead.
            @lru_cache(None)
            def dp_unrestricted(rem: int, rem_sum: int, prod_mod: int) -> int:
                if rem == 0:
                    return 1 if (rem_sum == 0 and prod_mod == 0) else 0

                res = 0
