                min_d = max(0, rem_sum - (rem - 1) * 9)
                max_d = min(9, rem_sum)

                for d in range(min_d, max_d + 1):
                    n_prod = (prod_mod * d) % target_sum
                    res += dp_unrestricted(rem - 1, rem_sum - d, n_prod)
                return res

            ans += count_up_to(R_digits, target_sum, dp_unrestricted)
            if L_digits:
